            <li class="breadcrumb-item"><a href="courses?departmentId=@course.DepartmentId">@course.Department.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h2>Description</h2>
            <p>@course.Description</p>

            <h2>Instructor</h2>
            <div class="card mb-3">
                <div class="card-body">
                    <h5 class="card-title">@course.Instructor.Name</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Instructor.Title</h6>
                    <p class="card-text">@course.Instructor.Bio</p>
                    <p class="card-text"><small class="text-muted">📧 @course.Instructor.Email</small></p>
                </div>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Course Details</strong></div>
                <ul class="list-group list-group-flush">
                    <li class="list-group-item"><strong>Code:</strong> @course.Code</li>
                    <li class="list-group-item"><strong>Credits:</strong> @course.Credits</li>
                    <li class="list-group-item"><strong>Schedule:</strong> @course.Schedule</li>
                    <li class="list-group-item"><strong>Department:</strong> @course.Department.Name</li>
                </ul>
            </div>
            <a href="enroll?courseId=@course.Id" class="btn btn-success w-100 mt-3">Enroll in This Course</a>
            <a href="courses" class="btn btn-outline-secondary w-100 mt-2">Back to Courses</a>
        </div>
    </div>
}

@code {
